module.exports = { ADDITIONAL_CAMPAIGNS: CAMPAIGNS, ADDITIONAL_CAMPAIGN_NARRATION: NARRATION, ADDITIONAL_CAMPAIGN_METADATA: METADATA, ADDITIONAL_CAMPAIGN_CHARACTERS: CHARACTERS };
